class LedgerDistributor:
    def distribute(self, total_cents: int, beneficiaries: list[Beneficiary]) -> dict[str, int]:
        if not beneficiaries or total_cents <= 0:
            return {b.name: 0 for b in beneficiaries}
        total_weight = sum(b.weight for b in beneficiaries)
        if total_weight == 0:
            return {b.name: 0 for b in beneficiaries}

        bases = {}
        remainders = {}
        for b in beneficiaries:
            numerator = total_cents * b.weight
            q = numerator // total_weight
            r = numerator % total_weight
            bases[b.name] = q
            remainders[b.name] = r

        sum_base = sum(bases.values())
        R = total_cents - sum_base  # number of extra cents to distribute

        # Sort by remainder descending, then name ascending for deterministic tie-breaking
        sorted_beneficiaries = sorted(beneficiaries, key=lambda b: (-remainders[b.name], b.name))

        res = bases.copy()
